e['start']??2023));?><div class="career-timeline" style="--career-track-color:<?=$e($timeline['events'][0]['color']??'var(--efu-main)')?>" role="group" aria-label="<?=$e($timeline['aria_label']??$career['title']??'')?>"><p class="career-track-label"><?=$e($timeline['track_label']??$career['label']??'')?></p><div class="career-timeline-axis" aria-hidden="true"></div><i class="career-timeline-tick career-timeline-tick--start"></i><i class="career-timeline-tick career-timeline-tick--end"></i><ul class="career-track" aria-label="<?=$e(Theme::t('careerStages'))?>"><?php foreach($timeline['events']??[] as $event):?><li class="career-event <?=empty($event['to'])?'career-event--point':''?>" tabindex="0" aria-label="<?=$e(($event['label']??'').'，'.($event['period']??(($event['from']??'').' — '.($event['to']??$event['from']??''))))?>" style="--career-left:<?=100*(($event['from']??0)-($timeline['start']??0))/$span?>%;--career-width:<?=100*(($event['to']??$event['from'])-$event['from'])/$span?>%;--career-color:<?=$e($event['color']??'var(--efu-main)')?>"><span class="career-event-bar"></span></li><?php endforeach;?></ul><div class="career-timeline-years"><span><?=$e($timeline['start_label']??$timeline['start'])?></span><span><?=$e($timeline['end_label']??$timeline['end'])?></span></div></div><?php endif;?></div></article></div>
