<div class="author-content about-row about-row--interests"><?php foreach($s['items']??[] as $item):?><article class="author-content-item interest-card interest-card--<?=$e($item['variant']??'media')?>" tabindex="0" style="--interest-background:url('<?=$m($item['background']??'')?>');--interest-color:<?=$e($item['color']??'var(--efu-main)')?>"><div class="interest-card-content"><p class="author-content-item-tips"><?=$e($item['label']??'')?></p><h2 class="author-content-item-title"><?php foreach($item['title_lines']??[$item['title']??''] as $line):?><span><?=$e($line)?></span><?php endforeach;?><?php if(isset($item['mode']['image'])):?><img class="interest-mode-image" src="<?=$m($item['mode']['image'])?>" alt="<?=$e($item['mode']['name'])?>" title="<?=$e($item['mode']['tooltip']??$item['mode']['name'])?>"><?php endif;?></h2><div class="interest-card-footer"><?php if(isset($item['heroes'])):?><ul class="interest-heroes" aria-label="<?=$e(Theme::t('favoriteHeroes'))?>"><?php foreach($item['heroes'] as $i=>$hero):?><li style="--hero-index:<?=$i?>"><img src="<?=$m($hero['image'])?>" alt="<?=$e($hero['name'])?>" title="<?=$e($hero['name'])?>"></li><?php endforeach;?></ul><?php endif;?><?php if(!empty($item['subtitle'])):?><p class="interest-subtitle"><?=$e($item['subtitle'])?></p><?php endif;?><?php if(!empty($item['right_text'])):?><p class="interest-right-text" title="<?=$e($item['right_tip']??'')?>"><?=$e($item['right_text'])?></p><?php endif;?><?php if(isset($item['button'])):?><a class="about-card-button" href="<?=$e(Theme::url($item['button']['url']))?>" <?=!empty($item['button']['external'])?'target="_blank"':''?> rel="noopener noreferrer"><?php if(!empty($item['button']['icon'])):?><i class="<?=$e($item['button']['icon'])?>"></i><?php endif;?><span><?=$e($item['button']['text'])?></span></a><?php endif;?></div></div></article><?php endforeach;?></div>
<?php break;case 'stats_profile':?>
